  margin-right: 8px;
}
.bi-chatbox {
  margin-bottom: -5px;
}

.child-right {
  text-align: right;
}
.child-left {
  text-align: left;
}

.socialmedia {
  display: flex;
  margin-top: 40px;
  max-width: 600px;

