}

.footer {
  padding-bottom: 20px;
}

.footer_p1 {
  margin-top: 30px;
  color: #9ca0a8;
  margin-bottom: 30px;
}

.footer_p2 {
    color: #383838;
    font-weight: bold;
}


.image {
  width: 200px;
  margin-top: 30px;
  margin-bottom: 30px;
}

.div-block {
  display: table;
  margin-top: 20px;
  margin-bottom: 40px;
  flex-direction: row;
  justify-content: center;
  align-items: center;
}

.terms_of_use {
  color: #9ca0a8;
}

.text-block-3 {
  color: #9ca0a8;
  margin-bottom: 30px;
}

.line_image,
.line {
  width: 100%;
  height: 13px;
  margin-top: 40px;
}

.line_image {
  background-image: linear-gradient(90deg, #c58d38, #c58d38 0%, #f3cd7c 35%, #dbb056 54%, #eec05f 63%, #cc9d3d);
}

.line {
  background-image: linear-gradient(90deg, #c58d38, #f3cd7c 40%, #dbb056 55%, #eec05f 71%, #cc9d3d);
}
