  margin-bottom: 30px;
}

.div-block {
  display: table;
  margin-top: 20px;
  margin-bottom: 40px;
  flex-direction: row;
  justify-content: center;
  align-items: center;
}

.terms_of_use {
  color: #9ca0a8;
}

.text-block-3 {
  color: #9ca0a8;
  margin-bottom: 30px;
}

.line_image,
.line {
  width: 100%;
