}

.footer {
  padding-bottom: 20px;
}

.footer_p1 {
  margin-top: 30px;
  color: #9ca0a8;
  margin-bottom: 30px;
}

.footer_p2 {
    color: #383838;
    font-weight: bold;
}


.image {
